def apply(sections,sources,source,section,table,cite):
 source('S32','DXR2 rendered functional specification','https://microsoft.github.io/DirectX-Specs/d3d/Raytracing2.html','v0.38 Intro says currently in preview. CLAS, cluster BLAS, PTLAS and indirect AS operations are specified; placeholder capability names remain. Conflicts with index maturity wording; no matching consumable SDK/driver pair established.',date='2026-09-08')
 source('S33','SM6.10 preview announcement','https://devblogs.microsoft.com/directx/shader-model-6-10-agilitysdk-720-preview/','April announcement exposes ClusterID but says clustered geometry not ready and tentatively targets fall. Neither intrinsic support nor spec text proves a complete runtime.',date='2026-04-27')
 source('S34','AMD tetrahedral cage memory demonstration','https://gpuopen.com/learn/how-tetrahedral-cages-significantly-reduce-bvh-memory-usage/','September demo: about 25k independently animated plants, 500M selected triangles, 1.7GB BVH and 3.3ms updates; primary/shadow at 1080p 60+fps on RX9070XT. Not a multi-bounce PT benchmark.',date='2026-09-17')
 source('S35','AMD tetrahedral cage technical article','https://gpuopen.com/learn/ray-tracing-massive-amounts-animated-geometry/','Coarse animated cages reuse static micro-BLASes. Article says official DXR samples and header-only cage-generation library are being developed; no released code license established here.',date='2026-07-22')
 source('S36','Ray Tracing Massive Amounts of Animated Geometry','https://gpuopen.com/download/TetrahedralMeshes_AuthorsVersion.pdf','Full author PDF read locally, 18 pages. pp4–10: clipping, affine instance method and 4D watertight method. pp12–16: overhead, performance and limitations. Fast path not guaranteed watertight; watertight variant has substantial overhead.',kind='research paper',date='2026-07-01',rights='Author-version p1 states personal use, not redistribution. Only link and original summaries shipped; PDF, extraction and screenshots remain private workbench evidence.')
 source('S37','AnandTech discussion supplied by user','https://forums.anandtech.com/threads/exciting-new-features-research-advancements-in-gaming-graphics-adjacent-software.2633516/page-7','Discovery context for cages, DGF, Work Lists and other leads. Forum claims are not used as technical proof or hardware roadmap confirmation.',kind='discussion / discovery only')
 source('S38','D3D12 Work Lists draft','https://microsoft.github.io/DirectX-Specs/d3d/WorkLists.html','v0.855, October21: implementations not ready, hopes for preview in 2027. Distinct from released Work Graphs. Do not require Work Lists for the current scheduler.',date='2026-10-21')
 source('S39','DGF SuperCompression','https://gpuopen.com/learn/introducing-amd-dgf-supercompression/','Geometry compression and CLAS are complementary. DGFS can decode to DGF blocks or ordinary indexed meshlets. Vendor storage results are not Basix results.',date='2026-05-07')
 source('S40','DGF SDK license-bearing source','https://github.com/GPUOpen-LibrariesAndSDKs/DGF-SDK/blob/main/DGFLib/DGF.h','MIT permission in DGF.h; repository LICENSE.md also lists dependencies. Candidate codec only, not adopted.',rights='MIT in inspected header; audit selected revision, dependencies and separate shader/data files before adoption. No code copied.')
 source('S41','vk_lod_clusters','https://github.com/nvpro-samples/vk_lod_clusters','Maintained raster/RT cluster-LOD and streaming sample. Root license Apache-2.0. Vendor RT path is not a standardized DXR2 implementation.',rights='Apache-2.0 root license; dependencies/assets require independent review. Reference only, not vendored.')
 source('S42','Independent tetrahedral cage implementation','https://github.com/bgyss/ray-tracing-tet-cage/tree/1d94ae44bbbd41b30e02a340dc66d3aa3337fb1d','Independent, not AMD sample; README documents remaining boundary/grazing probe differences. Portable math/preprocessing reference, not proven Vulkan/NVIDIA production renderer.',rights='Apache-2.0 LICENSE at 1d94ae44bbbd41b30e02a340dc66d3aa3337fb1d; retain notices if adopted. No source adopted by Basix.')
 source('S43','meshoptimizer license','https://github.com/zeux/meshoptimizer/blob/master/LICENSE.md','MIT mesh/meshlet optimization candidate. Basix should evaluate offline clustering, LOD and codecs separately from acceleration structures.',rights='MIT at inspected mutable branch; pin a revision and audit chosen files before adoption. No code copied.')
 source('S44','Basix local correctness experiment','https://github.com/BasixMaster/Basix_Engine/blob/main/IMPLEMENTATION.md','Local 2026-10-28 MSVC19.44/SDK26100, Slang2026.18.2, headers1.4.357, RTX4090/NVIDIA617.42. CPU 78 checks; GPU pointer-root4096 pixels and hardware ray-query8192 results across two transforms. Correctness only; no validation-layer pass or performance claim.',kind='local implementation / measured correctness',rights='Original Basix code MIT; dependencies retain separate licenses.')
 source('S45','Microsoft Work Graphs release','https://devblogs.microsoft.com/directx/d3d12-work-graphs/','Work Graphs1.0 was released March11,2024. Distinct from later Work Lists design; optional scheduling experiments still require hardware/runtime support and measured workload benefit.',date='2024-03-11')
 for s in sources:
  if s['id']=='S15':s['notes']='GitHub draft v0.38; rendered version S32 says preview while index S14 says not-preview. Matching public SDK/driver combination not established. Preserve source disagreement.'
  if s['id']=='S36':s['published_on']=''
  if s['id']=='S37':s['quality']='Discussion used for discovery only; claims require independent primary-source verification.'
  if s['id']=='S44':s['quality']='Local correctness checks with independent CPU oracles; hardware/configuration and untested scope are explicit.'

 by={s['id']:s for s in sections}
 by['summary']['body']=by['summary']['body'].replace('proposed architecture, not implemented','architecture with an initial tested foundation').replace('No renderer was implemented, no GPU benchmarks were run, and no visual parity has been demonstrated.','An initial NoGraphicsAPI/Vulkan hardware-ray-query experiment and CPU cage math are implemented and locally tested. No performance benchmark or UE visual parity has been demonstrated.').replace('All budgets and milestones below are design proposals.','Budgets are proposals; implementation status is recorded separately below.')
 by['summary']['body']+='<p><a href="#implementation-status">See the tested foundation</a> · <a href="#idea-pool">Expanded idea pool</a> · <a href="#tetra-cages">Tetrahedral cages</a></p>'
 by['dx-roadmap']['body']=by['dx-roadmap']['body'].replace('Official status index: work in progress, not in preview yet.','Conflicting official status: detail spec says preview; index says not-preview. Consumable SDK/driver combination unverified.').replace('Draft forecast dates are not a shipping commitment.','Draft forecast dates are not a shipping commitment. See the expanded idea pool for CLAS/PTLAS gates.')
 by['dx-roadmap']['body']+='<p><strong>Correction after rechecking:</strong> the rendered DXR2 specification explicitly says preview, despite the index’s older label. Basix therefore tracks the feature as “spec reports preview; package/driver implementation unverified,” rather than asserting a firm unavailable or shipping status.</p>'+cite('S32','S33')
 by['license']['body']=by['license']['body'].replace('This documentation repository currently contains no engine or NVIDIA SDK code.','The repository now contains original MIT experimental C++/Slang code; no NVIDIA SDK code or binaries are vendored.')
 by['lessons']['body']=by['lessons']['body'].replace('NoGraphicsAPI provides a compact model, but hardware RT and SDK interoperability are missing public seams.','NoGraphicsAPI provides a compact model; Basix now proves one Vulkan hardware-ray-query seam while SDK texture interoperability remains open.').replace('no local rendering experiments, cross-vendor benchmarks or shipping legal review were performed.','local correctness experiments are narrow; no cross-vendor benchmarks or shipping legal review were performed.').replace('The first next step is M0/M1, followed by a decision on Windows/Vulkan-first versus immediate D3D12 investment.','The next step is to harden M1 state/resource contracts and add a material/reference-renderer slice, while keeping geometry experiments independent.')
 by['research-map']['body']+='<p><strong>Q7 · High:</strong> can cages preserve acceptable deformation and ray correctness while reducing full-frame cost? Compare independent deformed triangles, shared-face/grazing cases and ordinary BLAS; stop research at separate fast/reference variants and measurable adoption gates. <strong>Q8 · High:</strong> which geometry ideas are complementary? Separate compression, LOD, AS organization and deformation; require independently queried capabilities.</p>'
 by['roadmap']['body']='''<p>Revised ordering: establish the tested base first, harden its lifecycle/SDK seam, then grow materials and content. Geometry research proceeds on separate branches so a draft standard or a cage limitation cannot block the whole engine. “Passed” below refers only to the named experiment.</p>'''+table(['Gate','Current state / next deliverable','Acceptance condition'],[
 ('M0a · CPU base','Implemented C++20 offline target and 78 cage-math checks.','Passed locally and in Linux/Windows CPU CI for implementation commit923d10b.'),
 ('M0b · GPU base','Implemented pinned NoGraphicsAPI fork preparation, Slang pointer ABI smoke and local dependency lock.','4096 GPU values match CPU oracle on RTX4090. Cross-vendor and independent SPIR-V validation remain open.'),
 ('M1a · Hardware RT seam','Implemented same-device Vulkan BLAS/TLAS, native command scope and static/translated ray queries.','8192 oracle checks passed. No DXR2, cage GPU traversal or SDK integration claim.'),
 ('M1b · Harden interop','Next: debug validation, texture handles/layouts, external SDK state restoration, window resize and device-loss behavior.','Validation/capture on real hardware; repeated create/destroy and renderer/SDK transitions correct.'),
 ('M2 · Reference renderer','Next: stable scene/material IDs, shared BSDF, geometry import, progressive reference PT and guide semantics.','Reference convergence, PDF/energy tests and motion-vector clips.'),
 ('M3 · Many lights / reconstruction','Original DI/fallback denoising, optional RTXDI; SR then RR through explicit adapter.','Equal-error captures and temporal tests, transparent licenses and non-DLSS path.'),
 ('G1 · Mesh/stream contract','Stable clusters, codec tags, residency generations, original material/triangle provenance, conventional BLAS.','Deterministic cook, bounded residency and correct stale-handle rejection. meshoptimizer/DGF remain candidate dependencies.'),
 ('G2 · Cages','CPU affine math implemented. Next: triangle clipping, shared-boundary provenance, generation quality and GPU adjacent-cell probe.','No holes/duplicates under declared tolerance; fast method never called watertight. Fallback when deformation invalid.'),
 ('G3 · Cluster AS','Optional NV cluster experiment first if supported; separate standardized DXR2 adapter later.','Actual queried support and CLAS→clusterBLAS→TLAS tests, relocation/residency lifetime proof.'),
 ('G4 · Geometry comparison','Compare standard skin/refit, rigid instances, clusters and cages on repeated foliage and diverse assets.','Total frame time, peak memory, TLAS/update/traversal cost and image/deformation error; not triangle counts alone.'),
 ('M4 · Game slice','Streaming district, animation, physics/audio/input and save/load after the renderer foundation.','Reproducible playable scene and packaged assets; game-specific destruction only if required.'),
 ('R · Optional research','DGF/DGFS, LinAlg, caches, Work Graphs and future Work Lists.','Each feature beats its baseline within a quality/memory budget; no unsupported mandatory path.')])+'''
<p>DXR2 promotion requires a matching header/runtime/compiler/driver, successful capability query, CLAS build, trace, relocation and destruction under validation. No placeholder API name is compiled into this implementation. Cage promotion additionally requires stable previous/current deformation, emissive-light PDF handling and multi-bounce/reconstruction tests.</p>
<p>Every GPU result must state adapter/driver, internal/output resolution, sample/bounce count, rendered versus generated FPS, p95 frame time, VRAM and AS scratch peaks. Current results are correctness-only; no 60fps or UE-quality claim follows from them. See <a href="implementation-results.json">implementation receipt</a> and <a href="verification.json">documentation checks</a>.</p>'''

 section('idea-pool','Idea pool: geometry, scheduling and neural rendering', '''
<p>These ideas solve different costs. Preserve interchangeable boundaries instead of committing the engine’s asset format or scheduler to one vendor or unshipped standard.</p>'''+table(['Idea / priority','What it changes','Proposed disposition / fallback'],[
 ('DXR2 Clustered Geometry · high','CLAS fragments can be reused and assembled into cluster BLAS; potentially cheaper LOD/streaming/deformation rebuilds.','Experimental adapter; ordinary triangle BLAS remains the current path.'),
 ('Partitioned TLAS · high','Partitions instance updates/translation for large, changing worlds.','Future independent capability; retain conventional TLAS and camera-relative scene partitioning.'),
 ('Indirect AS operations · high','GPU supplies batches/addresses for fine-grained AS work.','Pair with explicit scratch/AS ownership and fence retirement. Do not assume indirect operations remove allocation/lifetime costs.'),
 ('Tetrahedral cages · high for dense animation','Reuse static dense microgeometry while deforming coarse cells.','Separate preprocessing/animation experiment; conventional skinned BLAS or rigid instances when unsuitable.'),
 ('Meshlet LOD / residency · high','Limits working set and draw/trace work with view/error budgets.','Implement stable IDs/provenance first. Inspect meshoptimizer MIT and vk_lod_clusters Apache2 references before code adoption.'),
 ('DGF / DGFS · medium','Compresses geometry/streaming payloads; orthogonal to CLAS organization.','Codec option with decoded indexed-meshlet fallback, not mandatory future hardware.'),
 ('OMM / SER · medium','Reduces alpha traversal/shader-divergence cost on suitable hardware/workloads.','Independent optional capabilities after opaque baseline; measure build/memory overhead too.'),
 ('Work Lists · watchlist','GPU-selected programs/PSOs and work records. Draft hopes for preview2027.','Do not block current engine; use indirect dispatch and explicit PSO buckets.'),
 ('Work Graphs · optional','GPU work expansion/scheduling with a different execution model.','D3D12 experiment only when it improves measured workload; not synonymous with Work Lists.'),
 ('LinAlg / neural caches · later','Shader inference for material/cache/compression experiments.','Require conventional baseline, model/data license and complete update/invalidation costs.'),
 ('SDF / sparse representations · game-specific','Compact procedural fields and topology-changing destruction.','Complement triangle content only when gameplay/art warrants representation limits; PETAFAB is inspiration, not a general PT proof.')])+cite('S32','S38','S39','S40','S41','S43','S45')+'''
<figure class="pipeline"><div>Source asset + provenance</div><div>Encoding: ordinary mesh / DGF / DGFS → meshlets and LOD residency</div><div class="branches"><span>Ordinary BLAS or optional CLAS / cluster BLAS</span><span>Cage clipping → reusable micro-BLAS + animated cells</span></div><div>Conventional TLAS or optional PTLAS → common materials / lighting / reconstruction</div><figcaption>Proposed orthogonal layers. A meshlet, compression block, CLAS and tetrahedron are different units with separate lifetimes.</figcaption></figure>
<p>The current machine advertises <code>VK_NV_cluster_acceleration_structure</code>, but the implemented test uses ordinary BLAS/TLAS only. NV cluster capability is not proof of standard DXR2 support. The RTXMG reference uses NVAPI on D3D12 and NV cluster extensions on Vulkan. Do not collapse these names into one portable API.</p>'''+cite('S23')+'''
<p><strong>Research leads deferred:</strong> forum mentions of GATE, future tetrahedron hardware and DXR3/console adoption have no validated implementation gate here. TE-SDF addresses collision distance queries; SDFRaster is an offline reconstruction lead. They are not confirmed rendering accelerators for Basix. The supplied discussion remains discovery context, with primary evidence taking precedence.</p>'''+cite('S37'))

 section('tetra-cages','Tetrahedral cages: reusable detail under deformation', '''
<p>Instead of rebuilding the dense mesh’s BLAS for every animation, preprocess a coarse cage and keep reusable static micro-BLASes. The original surface must be clipped at cell boundaries; retain material/UV/original-triangle provenance and consistent shared vertices. Each cell then supplies one affine deformation.</p>'''+cite('S35')+'''
<div class="callout"><strong>Affine-cell model · original mathematical explanation</strong><p>Let R and A contain the three rest and animated edge vectors as columns. Then <code>x′ = a₀ + A R⁻¹ (x − r₀)</code>. Transform rays by the inverse without normalizing their direction, so the original parameter t stays comparable. Transform normals by the inverse transpose. Singular or inverted cells require rejection or an explicit fallback.</p></div>
<p>The Basix CPU implementation tests this mathematical layer only. It does not yet generate cages, clip surface triangles, serialize assets or trace adjacent-cell micro-BLASes on the GPU.</p>
'''+table(['Variant','Guarantee / tradeoff','Adoption gate'],[
 ('Fast hardware instances','Affine transforms with ordinary static triangle micro-BLASes. Neighboring cells can disagree at shared boundaries.','Never label watertight; test grazing/shadow rays and duplicate-hit handling.'),
 ('Watertight 4D reference','Consistent barycentric representation/reconstruction; different custom traversal route.','Paper reports 19–80× render overhead and 2.3–3.2× memory versus fast variant in tested scenes. Use as correctness research, not a demonstrated realtime option.'),
 ('Conventional skin/refit','Stores/updates actual deformed triangle geometry.','Baseline and fallback for sharp joints, fine facial/cloth motion, topology changes or invalid cages.')])+'''
<p>The paper’s expanded-plane epsilon is scene-dependent; absence of leaks in its experiment is not a proof for all assets. It reports preprocessing growth of 1.3–2.3× triangles and 1.4–3.7× vertices in tested assets. Cage/TLAS instance overhead and traversal can offset saved dense-BVH updates.</p>'''+cite('S36')+'''
<p>AMD’s later September demonstration reports about 25k plants and 500M selected triangles, about 1.7GB BVH and 3.3ms updates at 1080p/60+fps on RX9070XT. It traces primary/shadow rays. These are vendor results from a separate scene, not Basix measurements or evidence for multi-bounce PT with RR.</p>'''+cite('S34')+'''
<h3>Proposed experiment sequence</h3><ol><li>CPU cell/ray math: implemented, 78 checks.</li><li>Clip triangles into cells, deduplicate boundary provenance and test coverage/attributes independently.</li><li>Compare one-cell and adjacent-cell GPU instances to independently deformed triangles; include seams, grazing rays and invalid deformation.</li><li>Run a foliage reuse-count/cage-resolution sweep; measure animation, TLAS generation, AS updates, traversal, full-frame time and total memory.</li><li>Add previous/current cage motion, emissive-area/PDF updates and multi-bounce reconstruction tests.</li></ol>
<p>The official article still describes samples/cage-generation code as in development. An independent Apache-2.0 implementation exists, but is not AMD’s released solution and documents unresolved probe differences. Basix’s current CPU code is original MIT; no external cage implementation was copied. The author PDF’s personal-use notice prevents redistributing that file here.</p>'''+cite('S35','S42','S36'))

 section('implementation-status','Implementation: tested foundation and open work', '''
<p><strong>Implemented now:</strong> a C++20/CMake foundation, original CPU cage math/tests, explicit pinned NoGraphicsAPI fork preparation, a Slang pointer-root GPU test, and same-device Vulkan BLAS/TLAS/ray-query experiments. The default CPU build works without external dependencies; GPU dependencies are explicit local opt-ins.</p>'''+table(['Local result · 28 Oct 2026','Scope','Limit'],[
 ('78 CPU checks passed','Affine mapping, ray t, clip intervals, normals, invalid cells, shared faces and world scales1e−100…1e100.','Double-precision cell reference; not preprocessing or GPU watertightness.'),
 ('4096 pointer-root pixels matched','GPU output from NoGraphicsAPI compute compared with independent CPU arithmetic.','One Slang ABI, one Windows/Vulkan adapter.'),
 ('8192 ray-query results matched','Ordinary hardware BLAS/TLAS for static and translated triangle; all pixels checked against analytic geometry.','No PT, DLSS, cages on GPU, clustered AS or shipping renderer.'),
 ('CMake/CTest passed locally','MSVC19.44, WindowsSDK26100, Slang2026.18.2, Vulkan headers1.4.357; RTX4090, NVIDIA617.42.','CPU/docs CI passed on Linux and Windows for implementation commit923d10b. GPU vendors beyond the local RTX4090 remain untested; no validation-layer/spirv-val pass claimed.')])+cite('S44')+'''
<div class="proof-grid"><figure><img src="assets/pointer-smoke.png" alt="GPU-produced red and green gradient"><figcaption>NoGraphicsAPI pointer-root smoke output, 64×64.</figcaption></figure><figure><img src="assets/ray-static.png" alt="Green triangle traced with hardware ray queries"><figcaption>Hardware ray query, static triangle.</figcaption></figure><figure><img src="assets/ray-moved.png" alt="The same traced triangle translated to the right"><figcaption>Same BLAS, translated TLAS instance.</figcaption></figure></div>
<p>These images are actual generated test outputs, enlarged by the browser. They are correctness evidence, not a visual-quality demo. See <a href="implementation-results.json">test receipt</a> and the repository’s <a href="https://github.com/BasixMaster/Basix_Engine/blob/main/IMPLEMENTATION.md">build instructions</a>.</p>
<p><strong>Next:</strong> validation-enabled GPU checks, explicit native texture/state contracts and renderer/SDK transitions; then shared materials and a progressive reference renderer. Window resize/device-loss handling, DLSS, full PT, streaming, cage preprocessing and DXR2 adapters remain open. No current result is presented as completion of those gates.</p>''')

def enrich_library(library):
 for q in library['questions']:
  if q['id']=='Q2':q['coverage']='Public API gap identified; original Vulkan ray-query extension and pointer-root GPU oracles passed locally. SDK texture/state validation remains open.'
 for f in library['findings']:
  if f['id']=='F4':f['claim']='DXR1.2 is retail and LinAlg is preview. DXR2 detail spec says preview while index/SDK evidence conflicts; actual consumable SDK/driver support remains unverified. UE6 is a future target.'
 library['summary']=['Expanded idea pool separates compression, geometry residency, AS organization and deformation. Original CPU and same-device GPU correctness experiments are implemented; performance and visual parity remain unverified.']
 for qid,title,anchor in [('Q7','Tetrahedral cages and deformation correctness','tetra-cages'),('Q8','Orthogonal geometry and scheduling ideas','idea-pool')]:
  library['questions'].append(dict(id=qid,title=title,topic='rendering',priority='high',status='complete',why='Select viable experiments without making draft standards mandatory.',depends_on=['Q2'],search_terms=[title],source_types=['primary specifications','paper','code licenses'],evaluation='Separate mechanisms, availability, correctness and measured end-to-end benefit.',stop_when='Research yields explicit independent implementation gates and unresolved validation tasks.',coverage='Sources evaluated; CPU math and basic hardware rays tested. Cluster/cage GPU scalability remains untested.',presentation_path='index.html',presentation_anchor=anchor))
 for fid,title,claim,qids,ids,kind in [
  ('F6','Cages trade update cost against correctness/traversal','Cage reuse is promising for dense repeated animation, but the fast hardware-instance method is not guaranteed watertight and requires preprocessing/fallback policy.',['Q7'],['S35','S36'],'reported'),
  ('F7','Geometry layers are complementary','DGF/DGFS encoding, meshlet residency, clustered AS and tetrahedral deformation solve different costs and should retain independent interfaces.',['Q8'],['S32','S39','S41'],'analytical'),
  ('F8','Initial implementation passed local oracles','CPU78 checks and GPU pointer4096 / ray8192 oracle checks passed on the stated local configuration. This does not validate PT, DLSS, DXR2 or GPU cages.',['Q2','Q7'],['S44'],'measured')]:
  library['findings'].append(dict(id=fid,title=title,question_ids=qids,topic='rendering',claim=claim,evidence_type=kind,confidence='high',context='Checked/implemented2026-10-28; source-specific or local experiment scope.',strengths='Traceable primary evidence and explicit local oracle.',limitations='No cross-vendor/performance or shipping-quality validation.',implications='Proceed through separate gates in the revised roadmap.',tags=['geometry','DXR2','cages','implementation'],evidence=[dict(source_id=i,locator='Linked section; paper locators in notes; IMPLEMENTATION.md for local checks',relation='supports',note='Supports scoped claim only.') for i in ids],presentation_path='index.html',presentation_anchor='implementation-status' if fid=='F8' else 'tetra-cages' if fid=='F6' else 'idea-pool'))
 library['actions'][0].update(title='Harden M1 texture/state and SDK boundary',finding_ids=['F2','F8'],rationale='Basic rays now run; prove validation and native resource/state contracts before renderer expansion.',success_criterion='Validation-enabled captures, resize/device-state transitions and SDK texture tagging have explicit passing tests.')
 library['scope_changes'].append('User added DXR2/clustered geometry, tetrahedral cages, alternative ideas and implementation authorization. Corrected contradictory DXR2 maturity wording; recorded local CPU/GPU correctness results.')
 library['search_log'].append(dict(date='2026-10-28',phase='update',engine='Official specifications, GPUOpen paper and linked primary repositories',query='DXR2 Clustered Geometry PTLAS tetrahedral cages DGF DGFS Work Lists meshlet streaming',source_ids=['S32','S33','S34','S35','S36','S37','S38','S39','S40','S41','S42','S43'],outcome='Feature boundaries, source conflicts, licenses and adoption gates documented; original CPU/GPU foundation implemented.'))
